@page "/chat"
@using sv_922ac5e387f6406cb6eaa3c5cce869ba.Services
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <ChannelSidebar Channels="channels"
                    ActiveChannelId="activeChannelId"
                    OnChannelSelected="SelectChannel" />

    <div class="message-area @(threadOpen ? "" : "expanded")">
        @if (activeChannel is not null)
        {
            <div class="message-area-header">
                <h2># @activeChannel.Name</h2>
                <p>@activeChannel.Description</p>
            </div>

            <div class="message-list" @onscroll="HandleScroll">
                @if (loadingMore)
                {
                    <div class="loading-indicator">Loading older messages...</div>
                }
                @foreach (var message in messages)
                {
                    <MessageBubble Message="message"
                                   ReplyCount="GetReplyCount(message.Id)"
                                   OnOpenThread="OpenThread"
                                   OnReact="(emoji) => AddReaction(message.Id, emoji)" />
                }
            </div>

            <MessageInput Placeholder="Message #@activeChannel.Name" OnSend="SendMessage" />
        }
        else
        {
            <div class="no-channel-selected">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </div>

    @if (threadOpen && threadRootMessage is not null)
    {
        <ThreadPanel RootMessage="threadRootMessage"
                     Replies="threadReplies"
                     OnClose="CloseThread"
                     OnReply="SendThreadReply" />
    }
</div>

@code {
    private List<Channel> channels = [];
    private List<Message> messages = [];
    private List<Message> threadReplies = [];
    private Dictionary<int, int> replyCounts = new();

    private int? activeChannelId;
    private Channel? activeChannel;
    private Message? threadRootMessage;
    private bool threadOpen;
    private bool loadingMore;

    private const int PageSize = 30;
    private int currentSkip;
    private bool hasMoreMessages = true;

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
    }

    private async Task SelectChannel(int channelId)
    {
        activeChannelId = channelId;
        activeChannel = channels.FirstOrDefault(c => c.Id == channelId);
        currentSkip = 0;
        hasMoreMessages = true;
        messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        currentSkip = messages.Count;
        await ChatService.MarkChannelReadAsync(channelId);
        await UpdateReplyCounts();
        CloseThread();
    }

    private async Task HandleScroll()
    {
        // Triggered on scroll; in a real app, JS interop would detect scroll-to-top
        if (!hasMoreMessages || loadingMore) return;

        loadingMore = true;
        var older = await ChatService.GetMessagesAsync(activeChannelId!.Value, currentSkip, PageSize);
        if (older.Count < PageSize) hasMoreMessages = false;
        messages.InsertRange(0, older);
        currentSkip += older.Count;
        loadingMore = false;
        await UpdateReplyCounts();
    }

    private async Task SendMessage(string content)
    {
        if (activeChannelId is null) return;
        var message = await ChatService.SendMessageAsync(activeChannelId.Value, content, null);
        messages.Add(message);
    }

    private async Task OpenThread(int messageId)
    {
        threadRootMessage = messages.FirstOrDefault(m => m.Id == messageId);
        if (threadRootMessage is null) return;
        threadReplies = await ChatService.GetThreadAsync(messageId);
        threadOpen = true;
    }

    private void CloseThread()
    {
        threadOpen = false;
        threadRootMessage = null;
        threadReplies = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (threadRootMessage is null || activeChannelId is null) return;
        var reply = await ChatService.SendMessageAsync(activeChannelId.Value, content, threadRootMessage.Id);
        threadReplies.Add(reply);
        UpdateReplyCount(threadRootMessage.Id);
    }

    private async Task AddReaction(int messageId, string emoji)
    {
        await ChatService.AddReactionAsync(messageId, emoji);
        // Refresh the message reactions locally
        if (activeChannelId is not null)
        {
            messages = await ChatService.GetMessagesAsync(activeChannelId.Value, 0, currentSkip);
        }
    }

    private int GetReplyCount(int messageId) =>
        replyCounts.TryGetValue(messageId, out var count) ? count : 0;

    private void UpdateReplyCount(int messageId)
    {
        replyCounts[messageId] = replyCounts.GetValueOrDefault(messageId) + 1;
    }

    private async Task UpdateReplyCounts()
    {
        replyCounts.Clear();
        foreach (var msg in messages.Where(m => m.ReplyToId is null))
        {
            var thread = await ChatService.GetThreadAsync(msg.Id);
            if (thread.Count > 0)
            {
                replyCounts[msg.Id] = thread.Count;
            }
        }
    }
}

